  function normalize(value=''){return String(value||'').normalize('NFKC').trim().toLowerCase().replace(/\s+/g,' ');}
  const byName=new Map();
  for(const row of rows)for(const name of row.names)byName.set(normalize(name),Object.freeze(row));
  function resolve(input={}){
    const names=Array.isArray(input.names)?input.names:[input.name];
    for(const name of names){const row=byName.get(normalize(name));if(row)return row;}
    return null;
  }
  function resolution(input={}){
    const row=resolve(input);
    if(!row)return Object.freeze({knownVariant:false,status:'unknown',urls:Object.freeze([]),record:null});
    if(row.status!=='exact')return Object.freeze({knownVariant:true,status:'unavailable',urls:Object.freeze([]),record:row});
    const urls=[];
    if(String(input.gender||'').toLowerCase()==='f'&&row.femaleUrl)urls.push(row.femaleUrl);
    if(row.defaultUrl&&!urls.includes(row.defaultUrl))urls.push(row.defaultUrl);
    return Object.freeze({knownVariant:true,status:'exact',urls:Object.freeze(urls),record:row});
  }
  root.costumeSpriteCatalog=Object.freeze({schemaVersion:1,sourceId:"pokemondb-go-reviewed",normalize,resolve,resolution,records:Object.freeze(rows)});
